package numtools_test

import (
	"testing"

	"github.com/ai-verification/go-number-tools/internal/numtools"
)

func TestMaxInt(t *testing.T) {
	if numtools.MaxInt(3, 7) != 7 {
		t.Errorf("MaxInt(3,7) should be 7")
	}
	if numtools.MaxInt(10, 4) != 10 {
		t.Errorf("MaxInt(10,4) should be 10")
	}
}

func TestClamp(t *testing.T) {
	if numtools.Clamp(5, 1, 10) != 5 {
		t.Errorf("Clamp(5,1,10) should be 5")
	}
	if numtools.Clamp(-3, 0, 10) != 0 {
		t.Errorf("Clamp(-3,0,10) should be 0")
	}
	if numtools.Clamp(15, 0, 10) != 10 {
		t.Errorf("Clamp(15,0,10) should be 10")
	}
}

func TestSum(t *testing.T) {
	if numtools.Sum([]int{1, 2, 3, 4}) != 10 {
		t.Errorf("Sum([1,2,3,4]) should be 10")
	}
	if numtools.Sum([]int{}) != 0 {
		t.Errorf("Sum([]) should be 0")
	}
}
